-- params: ["done","done","2026-11-15T00:00:00.000Z","2026-11-24T00:00:00.000Z",1000]
-- database: agile_local
select "activities"."id", "activities"."project_id", "activities"."subproject_id", "activities"."sprint_id", "activities"."release_id", "activities"."user_story_id", "activities"."assignee_id", "activities"."created_by_id", "activities"."title", "activities"."description", "activities"."status", "activities"."priority", "activities"."work_type", "activities"."track", "activities"."percent_complete", "activities"."is_blocked", "activities"."blocked_reason", "activities"."due_date", "activities"."started_at", "activities"."completed_at", "activities"."created_at", "activities"."updated_at", "subprojects"."code", "subprojects"."name", "users"."full_name" from "activities" inner join "projects" on "projects"."id" = "activities"."project_id" left join "subprojects" on "subprojects"."id" = "activities"."subproject_id" left join "users" on "users"."id" = "activities"."assignee_id" where ("projects"."archived_at" is null and "activities"."due_date" is not null and ("activities"."status" <> $1 or ("activities"."status" = $2 and "activities"."completed_at" >= $3 and "activities"."completed_at" <= $4))) order by "activities"."due_date" asc, "activities"."id" asc limit $5;
